 "content": "def transform(grid):
    """Replace isolated one-cell noise with the locally interrupted color."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen[r][c] = True
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        stack.append((ny, nx))
            if len(component) != 1:
                continue
            y, x = component[0]
            counts = {}
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    if dy == 0 and dx == 0:
                        continue
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w:
                        v = grid[ny][nx]
                        counts[v] = counts.get(v, 0) + 1
            if not counts:
                continue
            best = max(counts.values())
            candidates = [v for v, n in counts.items() if n == best]
            chosen = candidates[0]
            if len(candidates) > 1:
                # A clear uninterrupted row band identifies the background
                # at a one-cell break in that band.
                row_counts = {}
                for v in grid[y]:
                    row_counts[v] = row_counts.get(v, 0) + 1
                row_color, row_n = max(row_counts.items(), key=lambda item: item[1])
                if row_n >= 0.8 * w and row_color in candidates:
                    chosen = row_color
                else:
                    # Prefer a color with an opposite pair, then the one with
                    # greatest continuation in a small neighborhood.
                    aligned = []
                    for v in candidates:
                        if ((x > 0 and x + 1 < w and grid[y][x - 1] == v == grid[y][x + 1]) or
                            (y > 0 and y + 1 < h and grid[y - 1][x] == v == grid[y + 1][x])):
                            aligned.append(v)
                    if len(aligned) == 1:
                        chosen = aligned[0]
                    else:
                        def support(v):
                            return sum(1 for dy in range(-2, 3) for dx in range(-2, 3)
                                       if (dy or dx) and 0 <= y + dy < h and 0 <= x + dx < w
                                       and grid[y + dy][x + dx] == v)
                        chosen = max(candidates, key=support)
            out[y][x] = chosen
    return out
